package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

public class ReproTest
{
  @Test
  public void testVulnerability() throws Exception
  {
    ObjectMapper mapper = new DefaultObjectMapper();

    // Inject a disabled config by default
    JavaScriptConfig disabledConfig = new JavaScriptConfig(false);
    InjectableValues.Std injectableValues = new InjectableValues.Std();
    injectableValues.addValue(JavaScriptConfig.class, disabledConfig);
    mapper.setInjectableValues(injectableValues);

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"function\": \"function(x){return x}\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    DimFilter filter = mapper.readValue(json, DimFilter.class);

    // Check if the filter thinks JS is enabled (it should be disabled via injection)
    // We can't access 'config' directly easily, but we can try to use it.
    // However, JavaScriptDimFilter.getPredicateFactory() checks config.isEnabled().

    if (filter instanceof JavaScriptDimFilter) {
       // We can use reflection or try to invoke something that checks the config.
       // optimize() returns 'this'
       // toFilter() creates a JavaScriptFilter which calls getPredicateFactory()

       try {
         filter.toFilter();
         // If we are here, it means config.isEnabled() returned true (or didn't throw)
         // But we injected 'false'. So if it works, the vulnerability is present (overridden by JSON).
         System.out.println("VULNERABILITY REPRODUCED: JavaScript execution allowed despite disabled injection.");
         Assert.fail("Vulnerability reproduced: JavaScript config overridden.");
       } catch (IllegalStateException e) {
         // Expected behavior: JavaScript is disabled
         System.out.println("Expected behavior: " + e.getMessage());
         Assert.assertEquals("JavaScript is disabled", e.getMessage());
       }
    }
  }
}

