    this.fieldNames = fieldNames;
    this.function = function;
  }

  @VisibleForTesting
  public JavaScriptPostAggregator(
      String name,
      List<String> fieldNames,
      String function,
      JavaScriptConfig config
  )
  {
    this(name, fieldNames, function);
    this.config = config;
